+// Client reproduces the reference client's choices exactly (hint selection,
+// coin stream, refresh order), so its request is the reduction of the
+// reference request, but stores its hints per superblock so that the
+// reduction can drop superblock keys.
+//
+// Every hint (primary or backup) is kept as the parities of its dropped
+// superblocks [0, d) and, when some keys are kept, the combined parity of the
+// kept superblocks [d, n). Backups also keep the parity of their own
+// superblock when it is a kept one, and the entry in their own chunk (xored
+// with the programmed value once promoted).
+type Client struct {
+	p  refwire.Params
+	l  layout
+	L  uint64 // primary hints
+	B  uint64 // backups (and replacements) per chunk
+	TB uint64 // all backups
+	d  uint64 // dropped superblocks
+
+	master safeaes.RoundKeys
+	sbox   [256]byte
+	jIn    [][16]byte // AES input block of each chunk position inside a superblock
+	rng    *coins
+
+	primD   [][2]uint64 // [h*d+b]: parity of dropped superblock b of primary hint h
+	primR   [][2]uint64 // [h]: parity of the kept superblocks (nil when d == n)
+	backD   [][2]uint64 // [t*d+b]
+	backR   [][2]uint64 // [t] (nil when d == n)
+	backBlk [][2]uint64 // [t]: parity of the backup's own superblock if kept (nil when d == n)
+	backPPV [][2]uint64 // [t]: entry in the backup's own chunk, xor programmed value
+	replVal [][2]uint64 // [g*B+k]
+	replOff []uint16
+
+	// First-hit table (see hits.go). Slots [0, tblPrefix) are recorded by
+	// one worker in increasing order; tblSeen exists only while preprocessing.
+	tblBits   uint
+	tblPrefix uint64
+	tbl8      []byte
+	tbl3      []uint64
+	tblSeen   []uint64
+	tblMiss   []uint64
+
+	used     []uint16 // per chunk: backups and replacements consumed
+	promoted []uint64 // bitmap over primary slots holding a promoted backup
+	slots    map[uint32]slotState
+	plist    []promotedSlot // promoted slots in increasing order
+	keyArena []safeaes.RoundKeys
+	hitHist  []uint32
+	qHist    []uint64
+
+	last lastQuery
 }

