+package pir
+
+import (
+	"encoding/binary"
+	"sort"
+	"sync"
+	"sync/atomic"
+
+	"easypir/safeaes"
+)
+
+// Hit search: the reference uses, for index x, the first primary slot (in
+// index order) whose current set contains x, skipping a slot whose programmed
+// point lies in x's chunk. Evaluating a slot costs a key derivation and an
+// AES key expansion, so the client avoids scanning:
+//
+//   - a first-hit table, built during preprocessing, holds for every index the
+//     residue modulo 2^tblBits of the first slot whose original set contains
+//     it (i0); only slots in i0's residue class are evaluated to find it;
+//   - a slot that has never been consumed still holds its original set, so
+//     the first unconsumed containing slot is i0, or (if i0 was consumed) the
+//     next unconsumed slot after it whose original set contains x;
+//   - consumed slots hold promoted backups; they are kept in a sorted list
+//     with their expanded keys, and checked with one AES call each.
+
+const none = ^uint64(0)
+
+type promotedSlot struct {
+	slot       uint64
+	labelChunk uint64 // chunk of the programmed point: the slot is skipped there
+	keys       uint64 // index of the slot's n expanded superblock keys in keyArena
+}
+
+func (c *Client) tblGet(x uint64) uint64 {
+	if c.tbl8 != nil {
+		return uint64(c.tbl8[x])
+	}
+	return c.tbl3[x/21] >> (3 * (x % 21)) & 7
+}
+
+// tblRecord stores the residue of slot h for index x unless x already has one.
+// Only the single recording worker calls it, in increasing slot order.
+func (c *Client) tblRecord(x, h uint64) {
+	w, bit := x>>6, uint64(1)<<(x&63)
+	if c.tblSeen[w]&bit != 0 {
+		return
+	}
+	c.tblSeen[w] |= bit
+	if c.tbl8 != nil {
+		c.tbl8[x] = byte(h)
+		return
+	}
+	i, sh := x/21, 3*(x%21)
+	c.tbl3[i] = c.tbl3[i]&^(7<<sh) | (h&7)<<sh
+}
+
+// finishTable lists the indices whose first slot lies beyond the recorded
+// prefix and drops the preprocessing bitmap.
+func (c *Client) finishTable() {
+	for w, word := range c.tblSeen {
+		for word != ^uint64(0) {
+			b := uint64(0)
+			for word>>b&1 != 0 {
+				b++
+			}
+			c.tblMiss = append(c.tblMiss, uint64(w)*64+b)
+			word |= 1 << b
+		}
+	}
+	c.tblSeen = nil
+}
+
+func (c *Client) tblMissing(x uint64) bool {
+	i := sort.Search(len(c.tblMiss), func(i int) bool { return c.tblMiss[i] >= x })
+	return i < len(c.tblMiss) && c.tblMiss[i] == x
+}
+
+func (c *Client) isPromoted(i uint64) bool {
+	return c.promoted[i>>6]>>(i&63)&1 != 0
+}
+
+// scanOriginal returns the first slot i in lo, lo+step, ... below hi whose
+// original set contains offset off of the chunk (superblock sb, AES input jIn
+// for the chunk's position), skipping promoted slots if asked; none if none.
+// Candidates are evaluated four at a time with expand4, one group ahead.
+func (c *Client) scanOriginal(lo, step, hi uint64, skipPromoted bool, sb, off uint64, jIn *[16]byte) uint64 {
+	var idx [2][4]uint64
+	var cnt [2]int
+	var tagIn, keys [4][16]byte
+	var rks [2][4]safeaes.RoundKeys
+	var out [16]byte
+	i := lo
+	// fill collects the next (up to) four candidates into group g and
+	// expands their keys.
+	fill := func(g int) {
+		k := 0
+		for k < 4 && i < hi {
+			if !skipPromoted || !c.isPromoted(i) {
+				binary.LittleEndian.PutUint64(tagIn[k][:8], i<<35+sb)
+				idx[g][k] = i
+				k++
+			}
+			i += step
+		}
+		cnt[g] = k
+		for q := 0; q < k; q++ {
+			safeaes.MMO(&c.master, &keys[q], &tagIn[q])
+		}
+		if k > 0 {
+			expand4(&c.sbox, &keys, &rks[g])
+		}
+	}
+	fill(0)
+	for g := 0; cnt[g] > 0; g ^= 1 {
+		fill(g ^ 1)
+		for q := 0; q < cnt[g]; q++ {
+			safeaes.MMO(&rks[g][q], &out, jIn)
+			if binary.LittleEndian.Uint64(out[:8])&c.l.mask == off {
+				return idx[g][q]
+			}
+		}
+	}
+	return none
+}
+
+// searchOriginal is scanOriginal over lo, lo+step, ... below hi: `inline`
+// candidates on the calling goroutine, then blocks of `block` candidates
+// taken in increasing order by four goroutines, keeping the smallest hit.
+func (c *Client) searchOriginal(lo, step, hi uint64, skipPromoted bool, sb, off uint64, jIn *[16]byte, inline, block uint64) uint64 {
+	end := lo + inline*step
+	if end > hi {
+		end = hi
+	}
+	if r := c.scanOriginal(lo, step, end, skipPromoted, sb, off, jIn); r != none || end >= hi {
+		return r
+	}
+	start, span := end, block*step
+	best := none
+	var counter uint64
+	work := func() {
+		for {
+			blo := start + (atomic.AddUint64(&counter, 1)-1)*span
+			if blo >= hi || blo >= atomic.LoadUint64(&best) {
+				return
+			}
+			bhi := blo + span
+			if bhi > hi {
+				bhi = hi
+			}
+			if r := c.scanOriginal(blo, step, bhi, skipPromoted, sb, off, jIn); r != none {
+				for {
+					cur := atomic.LoadUint64(&best)
+					if r >= cur || atomic.CompareAndSwapUint64(&best, cur, r) {
+						break
+					}
+				}
+			}
+		}
+	}
+	var wg sync.WaitGroup
+	for w := 0; w < 4; w++ {
+		wg.Add(1)
+		go func() {
+			defer wg.Done()
+			work()
+		}()
+	}
+	wg.Wait()
+	return best
+}
+
+// firstPromoted returns the first promoted slot below `below` whose current
+// set contains the index and that is not skipped for its chunk, or none.
+func (c *Client) firstPromoted(chunkID, sb, off, below uint64, jIn *[16]byte) uint64 {
+	var out [16]byte
+	for i := range c.plist {
+		e := &c.plist[i]
+		if e.slot >= below {
+			break
+		}
+		if e.labelChunk == chunkID {
+			continue
+		}
+		safeaes.MMO(&c.keyArena[e.keys*c.l.n+sb], &out, jIn)
+		if binary.LittleEndian.Uint64(out[:8])&c.l.mask == off {
+			return e.slot
+		}
+	}
+	return none
+}
+
+// findHit returns the slot the reference uses for the index.
+func (c *Client) findHit(chunkID, off uint64) uint64 {
+	l := c.l
+	sb, j := chunkID>>l.logS, chunkID&(l.s-1)
+	var jIn [16]byte
+	binary.LittleEndian.PutUint64(jIn[:8], j)
+	x := chunkID*l.chunk + off
+	// No unconsumed slot below `start` contains x: for a listed miss, none
+	// below the recorded prefix; otherwise none below i0, the first slot
+	// whose original set contains x.
+	i0, start := none, c.tblPrefix
+	if !c.tblMissing(x) {
+		m := uint64(1) << c.tblBits
+		i0 = c.searchOriginal(c.tblGet(x), m, c.tblPrefix, false, sb, off, &jIn, 8, l.chunk/m/32+8)
+		start = 0
+		if i0 != none {
+			start = i0
+		}
+	}
+	if i0 != none && !c.isPromoted(i0) {
+		if p := c.firstPromoted(chunkID, sb, off, i0, &jIn); p != none {
+			return p
+		}
+		return i0
+	}
+	p := c.firstPromoted(chunkID, sb, off, c.L, &jIn)
+	if p != none && p < start {
+		return p
+	}
+	hi := c.L
+	if p != none {
+		hi = p
+	}
+	if cand := c.searchOriginal(start, 1, hi, true, sb, off, &jIn, 32, l.chunk/256+32); cand != none {
+		return cand
+	}
+	if p == none {
+		panic("pir: no hit set found")
+	}
+	return p
+}
+
+// promote records that slot now holds backup `backup`, programmed with x.
+func (c *Client) promote(slot, backup, x uint64) {
+	st, was := c.slots[uint32(slot)]
+	i := sort.Search(len(c.plist), func(i int) bool { return c.plist[i].slot >= slot })
+	if !was {
+		st.keys = uint64(len(c.keyArena)) / c.l.n
+		c.keyArena = append(c.keyArena, make([]safeaes.RoundKeys, c.l.n)...)
+		c.plist = append(c.plist, promotedSlot{})
+		copy(c.plist[i+1:], c.plist[i:])
+		c.plist[i] = promotedSlot{slot: slot, keys: st.keys}
+		c.promoted[slot>>6] |= 1 << (slot & 63)
+	}
+	st.backup, st.label = uint32(backup), x
+	c.slots[uint32(slot)] = st
+	c.plist[i].labelChunk = x / c.l.chunk
+	// The slot's expanded superblock keys, four at a time.
+	tag := uint64(c.L + backup)
+	var tagIn, keys [4][16]byte
+	var rks [4]safeaes.RoundKeys
+	for b0 := uint64(0); b0 < c.l.n; b0 += 4 {
+		for q := uint64(0); q < 4; q++ {
+			binary.LittleEndian.PutUint64(tagIn[q][:8], tag<<35+b0+q)
+		}
+		for q := 0; q < 4; q++ {
+			safeaes.MMO(&c.master, &keys[q], &tagIn[q])
+		}
+		expand4(&c.sbox, &keys, &rks)
+		for q := uint64(0); q < 4 && b0+q < c.l.n; q++ {
+			c.keyArena[st.keys*c.l.n+b0+q] = rks[q]
+		}
+	}
+}
