+	"easypir/safeaes"
+)
+
+// AES-128 key schedules in Go. AESKEYGENASSIST has a low throughput, and one
+// schedule is a serial chain, so expanding four independent keys in one
+// interleaved loop is cheaper than four safeaes.ExpandKey calls. The output
+// layout is the one safeaes.ExpandKey produces (round keys as little-endian
+// words of their 16 bytes).
+
+func makeSbox() [256]byte {
+	var s [256]byte
+	p, q := byte(1), byte(1)
+	rotl := func(x byte, k uint) byte { return x<<k | x>>(8-k) }
+	for {
+		if p&0x80 != 0 {
+			p = p ^ p<<1 ^ 0x1B
+		} else {
+			p = p ^ p<<1
+		}
+		q ^= q << 1
+		q ^= q << 2
+		q ^= q << 4
+		if q&0x80 != 0 {
+			q ^= 0x09
+		}
+		s[p] = q ^ rotl(q, 1) ^ rotl(q, 2) ^ rotl(q, 3) ^ rotl(q, 4) ^ 0x63
+		if p == 1 {
+			break
+		}
+	}
+	s[0] = 0x63
+	return s
+}
+
+// subRot is SubWord(RotWord(w)) for a word read little-endian.
+func subRot(sb *[256]byte, w uint32) uint32 {
+	return uint32(sb[w>>8&0xff]) | uint32(sb[w>>16&0xff])<<8 | uint32(sb[w>>24])<<16 | uint32(sb[w&0xff])<<24
+}
+
+func expand4(sb *[256]byte, k *[4][16]byte, r *[4]safeaes.RoundKeys) {
+	a0, a1, a2, a3 := binary.LittleEndian.Uint32(k[0][0:4]), binary.LittleEndian.Uint32(k[0][4:8]), binary.LittleEndian.Uint32(k[0][8:12]), binary.LittleEndian.Uint32(k[0][12:16])
+	b0, b1, b2, b3 := binary.LittleEndian.Uint32(k[1][0:4]), binary.LittleEndian.Uint32(k[1][4:8]), binary.LittleEndian.Uint32(k[1][8:12]), binary.LittleEndian.Uint32(k[1][12:16])
+	c0, c1, c2, c3 := binary.LittleEndian.Uint32(k[2][0:4]), binary.LittleEndian.Uint32(k[2][4:8]), binary.LittleEndian.Uint32(k[2][8:12]), binary.LittleEndian.Uint32(k[2][12:16])
+	d0, d1, d2, d3 := binary.LittleEndian.Uint32(k[3][0:4]), binary.LittleEndian.Uint32(k[3][4:8]), binary.LittleEndian.Uint32(k[3][8:12]), binary.LittleEndian.Uint32(k[3][12:16])
+	r[0][0], r[0][1], r[0][2], r[0][3] = a0, a1, a2, a3
+	r[1][0], r[1][1], r[1][2], r[1][3] = b0, b1, b2, b3
+	r[2][0], r[2][1], r[2][2], r[2][3] = c0, c1, c2, c3
+	r[3][0], r[3][1], r[3][2], r[3][3] = d0, d1, d2, d3
+	rc := uint32(1)
+	for i := 4; i < 44; i += 4 {
+		a0 ^= subRot(sb, a3) ^ rc
+		b0 ^= subRot(sb, b3) ^ rc
+		c0 ^= subRot(sb, c3) ^ rc
+		d0 ^= subRot(sb, d3) ^ rc
+		a1 ^= a0
+		b1 ^= b0
+		c1 ^= c0
+		d1 ^= d0
+		a2 ^= a1
+		b2 ^= b1
+		c2 ^= c1
+		d2 ^= d1
+		a3 ^= a2
+		b3 ^= b2
+		c3 ^= c2
+		d3 ^= d2
+		r[0][i], r[0][i+1], r[0][i+2], r[0][i+3] = a0, a1, a2, a3
+		r[1][i], r[1][i+1], r[1][i+2], r[1][i+3] = b0, b1, b2, b3
+		r[2][i], r[2][i+1], r[2][i+2], r[2][i+3] = c0, c1, c2, c3
+		r[3][i], r[3][i+1], r[3][i+2], r[3][i+3] = d0, d1, d2, d3
+		rc <<= 1
+		if rc == 0x100 {
+			rc = 0x1B
+		}
+	}
+}
