index 0000000..1482d8b
--- /dev/null
+++ b/quarter_pir/code/pir/layout.go
@@ -0,0 +1,87 @@
+package pir
+
+import "easypir/refwire"
+
+// Wire layout shared by the client, the reduction and the server.
+//
+// The reference request carries SBNum superblock keys and SBSize explicit
+// offsets. The first `dropped` keys are removed by ReduceRequest; the client
+// keeps, for every hint, the parity of each of those superblocks itself (and
+// the parity of the remaining superblocks combined), so the server never needs
+// them. With every key dropped the request is just the bit-packed offsets.
+//
+// The response holds, for every superblock c, the candidate
+//
+//	A_c = E_c xor (xor of K_b over kept superblocks b != c)
+//
+// where E_c is the parity of the explicit offsets placed in superblock c and
+// K_b the parity of the key-defined entries of superblock b, followed by K_b
+// for every kept superblock (needed when a refreshed hint's programmed
+// superblock carries a re-sampled key).
+type layout struct {
+	n, s, chunk   uint64 // SBNum, SBSize, ChunkSize
+	logS          uint
+	mask          uint64 // ChunkSize - 1
+	width         uint   // offset bits
+	dropped       uint64 // keys removed from the request: superblocks [0, dropped)
+	requestBytes  int
+	responseWords int
+}
+
+// droppedKeys is the number of superblock keys the reduction removes. Each
+// dropped key costs one more stored parity per hint (primary and backup), so
+// it is bounded by the client storage the reference uses: all four keys at
+// 2^16 entries, one of 32 at 2^26 (where the rest of the budget holds the
+// first-hit table).
+func droppedKeys(p refwire.Params) uint64 {
+	if p.SBNum <= 4 {
+		return p.SBNum
+	}
+	return 1
+}
+
+func newLayout(p refwire.Params) layout {
+	l := layout{n: p.SBNum, s: p.SBSize, chunk: p.ChunkSize, logS: uint(p.SBSizeLog2),
+		mask: p.ChunkSize - 1, width: p.OffsetBits(), dropped: droppedKeys(p)}
+	l.requestBytes = int(l.n-l.dropped)*16 + int(l.s*uint64(l.width)+7)/8
+	l.responseWords = int(2*l.n-l.dropped) * 2
+	return l
+}
+
+// packOffsets writes the offsets LSB-first at `width` bits each into dst.
+func packOffsets(dst []byte, offsets []uint64, width uint) {
+	var acc uint64
+	var have uint
+	pos := 0
+	for _, o := range offsets {
+		acc |= o << have
+		have += width
+		for have >= 8 {
+			dst[pos] = byte(acc)
+			pos++
+			acc >>= 8
+			have -= 8
+		}
+	}
+	if have > 0 {
+		dst[pos] = byte(acc)
+	}
+}
+
+// unpackOffsets is the inverse of packOffsets.
+func unpackOffsets(src []byte, offsets []uint64, width uint) {
+	var acc uint64
+	var have uint
+	pos := 0
+	m := uint64(1)<<width - 1
+	for i := range offsets {
+		for have < width {
+			acc |= uint64(src[pos]) << have
+			pos++
+			have += 8
+		}
+		offsets[i] = acc & m
+		acc >>= width
+		have -= width
+	}
+}
