@@ -0,0 +1,66 @@
+package pir
+
+import (
+	"encoding/binary"
+	"math/rand"
+)
+
+// coins reproduces the reference coin stream, rand.New(rand.NewSource(seed))
+// read through Uint64, with a state that can be copied: the case-2 key
+// rejection sampling draws candidate keys ahead on a copy and advances the
+// real stream only past the accepted one.
+//
+// math/rand's source is an additive lagged Fibonacci generator: output t is
+// vec[feed] + vec[tap] (indices stepping down mod 607), stored back at feed.
+// After 607 outputs every vec entry has been overwritten by one of them, so
+// the state is rebuilt from the first 607 outputs of the real source, which
+// are replayed before the generator continues on its own.
+type coins struct {
+	tap, feed int
+	vec       [rngLen]int64
+	pending   []uint64 // first outputs, replayed in order
+}
+
+const (
+	rngLen = 607
+	rngTap = 273
+)
+
+func newCoins(seed int64) *coins {
+	src := rand.New(rand.NewSource(seed))
+	c := &coins{tap: 0, feed: rngLen - rngTap, pending: make([]uint64, rngLen)}
+	for t := 1; t <= rngLen; t++ {
+		x := src.Uint64()
+		c.pending[t-1] = x
+		c.vec[((rngLen-rngTap-t)%rngLen+rngLen)%rngLen] = int64(x)
+	}
+	return c
+}
+
+func (c *coins) Uint64() uint64 {
+	if len(c.pending) > 0 {
+		x := c.pending[0]
+		c.pending = c.pending[1:]
+		if len(c.pending) == 0 {
+			c.pending = nil
+		}
+		return x
+	}
+	c.tap--
+	if c.tap < 0 {
+		c.tap += rngLen
+	}
+	c.feed--
+	if c.feed < 0 {
+		c.feed += rngLen
+	}
+	x := c.vec[c.feed] + c.vec[c.tap]
+	c.vec[c.feed] = x
+	return uint64(x)
+}
+
+// key draws a 16-byte key as util.RandKey does.
+func (c *coins) key(k *[16]byte) {
+	binary.LittleEndian.PutUint64(k[0:8], c.Uint64())
+	binary.LittleEndian.PutUint64(k[8:16], c.Uint64())
+}
